import{_ as e,o as a,c as d,ag as o}from"./chunks/framework.C5oN-8Wt.js";const m=JSON.parse('{"title":"I/Q 分解器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/modules/iq_split/index.md","filePath":"v0.1.0-alpha/modules/iq_split/index.md"}'),r={name:"v0.1.0-alpha/modules/iq_split/index.md"};function i(l,t,h,n,c,p){return a(),d("div",null,[...t[0]||(t[0]=[o('<h1 id="i-q-分解器" tabindex="-1">I/Q 分解器 <a class="header-anchor" href="#i-q-分解器" aria-label="Permalink to &quot;I/Q 分解器&quot;">​</a></h1><p>适用：v0.1.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>iq_split</code> · 模块定义版本：5</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>从同一个复数样本中取出实部 I 和虚部 Q，形成两路实数输出。适合分别观察分量，或把复数处理结果送给实数处理模块。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>复数输出 → I/Q 分解器.in</code>，从 <code>i</code> 取实部、从 <code>q</code> 取虚部。可将两路再接到 I/Q 合成器，检验分解与合成的往返关系。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（复数输入）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>i</code>（I）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>q</code>（Q）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>向量输入按分量拆分，每个输出 item 的长度仍与输入相同。两路保持来自同一个复数 item 的对应位置，采样率不变。</p><p>I 和 Q 都有正负号，既不是包络也不是相位。需要理解复数信号时，应结合两个分量；只保留 I 会丢失 Q 中的信息。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>每个 item 的向量长度<br><code>vlen</code></td><td><code>1</code></td><td>范围 1 至 1024；Master 当前容量限制为 1–1024；采样率按 item 计。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>向量长度变化需要重新准备，并使上下游端口形状一致。该模块没有需要在运行中逐项调整的分解系数；数据变化来自实际输入。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="复数处理与-i-q-往返" tabindex="-1">复数处理与 I/Q 往返 <a class="header-anchor" href="#复数处理与-i-q-往返" aria-label="Permalink to &quot;复数处理与 I/Q 往返&quot;">​</a></h3><p><a href="../../../downloads/v0.1.0-alpha/complex-iq.cnsproj" download>下载 complex-iq.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>复数处理与 I/Q 往返</p><ul><li>观察复数旋转相量、乘 j 的相位变化及 I/Q 分解再合成；复数频谱保留正负频率。</li></ul><p>复数处理示例把复数加法器接入分解器，再将 <code>i</code>、<code>q</code> 接回合成器。分别观察分解器两路并与原复数流的 I/Q 显示核对，合成后的样本应恢复原值。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q 为什么不是固定延时后的 I？</strong> 只有特定的信号才具有这种相位关系，分解器不建立该关系。</p><p><strong>分量输出能直接当码元索引吗？</strong> 不能。码元判决需要对应的星座定义，应使用符号判决器。</p>',26)])])}const q=e(r,[["render",i]]);export{m as __pageData,q as default};
